export const BUDGET_OPTIONS = [
  { value: "", label: "Ще не визначились" },
  { value: "500", label: "до $500 / міс." },
  { value: "1500", label: "$500–1500 / міс." },
  { value: "5000", label: "$1500–5000 / міс." },
  { value: "10000", label: "понад $5000 / міс." },
] as const;

export type LeadFormField =
  | "firstName"
  | "lastName"
  | "email"
  | "phone"
  | "company"
  | "website"
  | "budget"
  | "message"
  | "consentMarketing";

export type LeadFormData = {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  company: string;
  website: string;
  budget: number | null;
  message: string;
  consentMarketing: boolean;
};

export type ParseResult =
  | { ok: true; data: LeadFormData }
  | { ok: false; errors: Partial<Record<LeadFormField, string>> };

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_RE = /^\+?[0-9 ()-]{7,20}$/;

function text(formData: FormData, name: LeadFormField, max = 200) {
  const value = formData.get(name);
  return typeof value === "string" ? value.trim().slice(0, max) : "";
}

export function parseLeadForm(formData: FormData): ParseResult {
  const data: LeadFormData = {
    firstName: text(formData, "firstName", 80),
    lastName: text(formData, "lastName", 80),
    email: text(formData, "email", 200).toLowerCase(),
    phone: text(formData, "phone", 20),
    company: text(formData, "company", 120),
    website: text(formData, "website", 200),
    budget: null,
    message: text(formData, "message", 2000),
    consentMarketing: formData.get("consentMarketing") === "on",
  };

  const errors: Partial<Record<LeadFormField, string>> = {};

  if (!data.firstName) errors.firstName = "Вкажіть ім'я";
  if (!data.lastName) errors.lastName = "Вкажіть прізвище";
  if (!EMAIL_RE.test(data.email)) errors.email = "Перевірте email";
  if (data.phone && !PHONE_RE.test(data.phone)) errors.phone = "Перевірте номер телефону";
  if (data.message.length < 10) errors.message = "Опишіть задачу хоча б одним реченням";

  const budget = text(formData, "budget", 10);
  if (budget) {
    if (!BUDGET_OPTIONS.some((option) => option.value === budget)) {
      errors.budget = "Оберіть бюджет зі списку";
    } else {
      data.budget = Number(budget);
    }
  }

  return Object.keys(errors).length > 0 ? { ok: false, errors } : { ok: true, data };
}

"use client";

import { useActionState } from "react";
import { submitLead, type SubmitLeadState } from "@/app/actions";
import { BUDGET_OPTIONS } from "@/lib/lead-form";

const initialState: SubmitLeadState = { status: "idle" };

const inputClass =
  "mt-1 block w-full rounded-md border border-slate-300 px-3 py-2 text-sm shadow-sm focus:border-indigo-500 focus:outline-none focus:ring-1 focus:ring-indigo-500";

export function LeadForm() {
  const [state, formAction, pending] = useActionState(submitLead, initialState);
  const errors = state.status === "invalid" ? state.errors : {};

  if (state.status === "ok") {
    return (
      <div className="space-y-2 py-8 text-center">
        <p className="text-lg font-medium">Дякуємо! Заявку отримано.</p>
        <p className="text-sm text-slate-600">Ми зв&apos;яжемося з вами протягом робочого дня.</p>
      </div>
    );
  }

  return (
    <form action={formAction} className="space-y-4" noValidate>
      <div className="grid gap-4 sm:grid-cols-2">
        <label className="block text-sm font-medium">
          Ім&apos;я
          <input name="firstName" autoComplete="given-name" className={inputClass} />
          {errors.firstName && <span className="mt-1 block text-xs text-red-600">{errors.firstName}</span>}
        </label>
        <label className="block text-sm font-medium">
          Прізвище
          <input name="lastName" autoComplete="family-name" className={inputClass} />
          {errors.lastName && <span className="mt-1 block text-xs text-red-600">{errors.lastName}</span>}
        </label>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="block text-sm font-medium">
          Email
          <input name="email" type="email" autoComplete="email" className={inputClass} />
          {errors.email && <span className="mt-1 block text-xs text-red-600">{errors.email}</span>}
        </label>
        <label className="block text-sm font-medium">
          Телефон
          <input name="phone" type="tel" autoComplete="tel" className={inputClass} />
          {errors.phone && <span className="mt-1 block text-xs text-red-600">{errors.phone}</span>}
        </label>
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <label className="block text-sm font-medium">
          Компанія
          <input name="company" autoComplete="organization" className={inputClass} />
        </label>
        <label className="block text-sm font-medium">
          Сайт
          <input name="website" type="url" placeholder="https://" className={inputClass} />
        </label>
      </div>

      <label className="block text-sm font-medium">
        Бюджет
        <select name="budget" defaultValue="" className={inputClass}>
          {BUDGET_OPTIONS.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
        {errors.budget && <span className="mt-1 block text-xs text-red-600">{errors.budget}</span>}
      </label>

      <label className="block text-sm font-medium">
        Що потрібно зробити?
        <textarea name="message" rows={4} className={inputClass} />
        {errors.message && <span className="mt-1 block text-xs text-red-600">{errors.message}</span>}
      </label>

      <label className="flex items-center gap-2 text-sm text-slate-600">
        <input name="consentMarketing" type="checkbox" className="h-4 w-4 rounded border-slate-300" />
        Хочу отримувати корисні матеріали від Studio Nova
      </label>

      <button
        type="submit"
        disabled={pending}
        className="w-full rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white hover:bg-indigo-700 disabled:opacity-60"
      >
        {pending ? "Надсилаємо…" : "Надіслати заявку"}
      </button>
    </form>
  );
}

